content.arguments:
{"command":"$files = @('./','./')
$u8 = New-Object System.Text.UTF8Encoding($false)
foreach($p in $files){
  $t = [System.IO.File]::ReadAllText($p, [System.Text.Encoding]::UTF8)
  $lines = $t -split "`n"
  $bodyLines = @()
  for($i=0; $i -lt $lines.Count; $i++){ if($lines[$i] -like 'EVIDENCE:*'){ break }; $bodyLines += $lines[$i] }
  $body = ($bodyLines -join "`n").TrimEnd("`n")
  $bb = $u8.GetBytes($body)
  $sha = [System.Security.Cryptography.SHA256]::Create().ComputeHash($bb)
  $h = (($sha | ForEach-Object { $_.ToString('X2') }) -join '').Substring(0,12)
  $last = $lines | Where-Object { $_ -like 'EVIDENCE:*' }
  "FILE=$(Split-Path $p -Leaf)  recomputeBytes=$($bb.Length)  recomputeHash=$h  match=$($last -eq ('EVIDENCE: ' + $p + '|' + $bb.Length + '|' + $h))"
  $ctx = [regex]::Matches($body, '\d+\s*-\s*\d+') | ForEach-Object { $_.Value }
  "  hyphenSamples=$([string]::Join(' , ', ($ctx | Select-Object -Unique)))"
}","description":"修正复算逻辑并列出连字符出现样式"}

