content.arguments:
{"command":"$files=@('./','./')
foreach($p in $files){
  "==== $(Split-Path $p -Leaf) ===="
  $all=[System.IO.File]::ReadAllText($p,[System.Text.Encoding]::UTF8) -split "`n"
  "总行数=$($all.Count)"
  "--- 标题 ---"
  $all | Where-Object { $_ -match '^#{1,3} ' } | ForEach-Object { $_ }
  "--- 末3行（可视化，· 代表行内容）---"
  $all[-3..-1] | ForEach-Object { "·" + $_ }
}","description":"读回文件标题结构与末尾三行"}

